ageId).IsUnique(); b.Entity<ImageProcessingJob>().HasOne<VehicleImage>().WithMany().HasForeignKey(x=>x.ImageId).OnDelete(DeleteBehavior.Cascade); b.Entity<ImageProcessingJob>().Property(x=>x.State).HasConversion<string>(); b.Entity<ImageProcessingJob>().HasIndex(x=>new{x.State,x.NextAttemptAt}); b.Entity<IdempotencyRecord>().HasKey(x=>x.Id); b.Entity<IdempotencyRecord>().HasIndex(x=>new{x.Operation,x.Key}).IsUnique(); b.Entity<IdempotencyRecord>().Property(x=>x.ResponseJson).HasColumnType("jsonb"); } }
