ew ListObjectsV2Request{BucketName=Bucket,Prefix=prefix,ContinuationToken=token},ct);foreach(var o in page.S3Objects??[])yield return new(o.Key,new DateTimeOffset(DateTime.SpecifyKind(o.LastModified,DateTimeKind.Utc)));token=page.IsTruncated==true?page.NextContinuationToken:null;}while(token is not null);} }




